import '../items/item_definition.dart';
import '../npc/npc_content.dart';
import '../state/player_event_journal.dart';
import '../state/runtime_game_state.dart';
import 'dialogue_model.dart';

enum DialogueChoiceIneligibility {
  missingRelationship,
  conditions,
  missingGiftRule,
  itemNotGiftable,
  missingItem,
  missingRequiredFact,
  acceptanceCapReached,
}

final class DialogueChoiceEligibility {
  const DialogueChoiceEligibility._(this.reason);

  const DialogueChoiceEligibility.available() : reason = null;

  const DialogueChoiceEligibility.unavailable(
    DialogueChoiceIneligibility this.reason,
  );

  final DialogueChoiceIneligibility? reason;
  bool get isAvailable => reason == null;
}

/// Shared runtime/editor evaluation for authored dialogue choices.
final class DialogueChoiceEligibilityService {
  const DialogueChoiceEligibilityService();

  DialogueChoiceEligibility evaluate({
    required DialogueChoice choice,
    required NpcRelationshipState relationship,
    required PlayerEventJournal journal,
    required double activePlaySeconds,
    required Map<String, int> inventoryCounts,
    required ItemDefinitionCatalog itemCatalog,
    NpcGiftRule? giftRule,
  }) {
    if (!choice.conditions.matches(
      relationship,
      journal: journal,
      activePlaySeconds: activePlaySeconds,
    )) {
      return const DialogueChoiceEligibility._(
        DialogueChoiceIneligibility.conditions,
      );
    }
    if (!choice.isGift) return const DialogueChoiceEligibility.available();
    if (giftRule == null) {
      return const DialogueChoiceEligibility._(
        DialogueChoiceIneligibility.missingGiftRule,
      );
    }
    if (itemCatalog.findById(giftRule.itemId)?.giftBehavior !=
        ItemGiftBehavior.giftable) {
      return const DialogueChoiceEligibility._(
        DialogueChoiceIneligibility.itemNotGiftable,
      );
    }
    if ((inventoryCounts[giftRule.itemId] ?? 0) <= 0) {
      return const DialogueChoiceEligibility._(
        DialogueChoiceIneligibility.missingItem,
      );
    }
    final requiredFactId = giftRule.requiredFactId;
    if (requiredFactId != null &&
        !relationship.learnedFactIds.contains(requiredFactId)) {
      return const DialogueChoiceEligibility._(
        DialogueChoiceIneligibility.missingRequiredFact,
      );
    }
    if (journal.count(
          kind: PlayerEventKind.itemGifted,
          subjectId: giftRule.itemId,
          targetId: relationship.npcId,
        ) >=
        giftRule.acceptanceCap) {
      return const DialogueChoiceEligibility._(
        DialogueChoiceIneligibility.acceptanceCapReached,
      );
    }
    return const DialogueChoiceEligibility.available();
  }
}
